import React, { useState, useEffect } from 'react';
import API from "../api/axios";
import { useNavigate } from "react-router-dom";
import { Mail, Lock, ArrowRight, X, ArrowLeft, ShieldCheck, Zap, CheckCircle2, Save } from 'lucide-react';

const EntryCard = ({ isOpen, onClose }) => {
  const navigate = useNavigate();

  const [isFlipped, setIsFlipped] = useState(false);
  const [loginView, setLoginView] = useState('login');
  const [loginOtpSent, setLoginOtpSent] = useState(false);

  const [signupStep, setSignupStep] = useState(1);
  const [signupOtpSent, setSignupOtpSent] = useState(false);

  // 🔥 LOGIN STATES
  const [loginEmail, setLoginEmail] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginError, setLoginError] = useState("");

  // 🔥 SIGNUP STATES
  const [signupEmail, setSignupEmail] = useState("");
  const [signupOtp, setSignupOtp] = useState("");
  const [signupName, setSignupName] = useState("");
  const [signupPhone, setSignupPhone] = useState("");
  const [signupAddress, setSignupAddress] = useState("");
  const [signupPassword, setSignupPassword] = useState("");
  const [signupError, setSignupError] = useState("");

  useEffect(() => {
    if (!isOpen) {
      setIsFlipped(false);
      setLoginView('login');
      setLoginOtpSent(false);
      setSignupStep(1);
      setSignupOtpSent(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  // 🔥 LOGIN FUNCTION
  const handleLogin = async () => {
    if (!loginEmail || !loginPassword) {
      setLoginError("Please fill email and password");
      return;
    }

    setLoginError("");

    try {
      const res = await API.post("/auth/login", {
        email: loginEmail,
        password: loginPassword,
      });

      localStorage.setItem("token", res.data.token);
      navigate("/dashboard");

    } catch (err) {
      setLoginError("Invalid email or password");
    }
  };

  // 🔥 SEND OTP
  const handleSendOtp = async () => {
    if (!signupEmail) {
      setSignupError("Enter email first");
      return;
    }

    try {
      await API.post("/auth/send-otp", { email: signupEmail });
      setSignupOtpSent(true);
      setSignupError("");
    } catch {
      setSignupError("Failed to send OTP");
    }
  };

  // 🔥 VERIFY OTP
  const handleVerifyOtp = async () => {
    if (!signupOtp) {
      setSignupError("Enter OTP");
      return;
    }

    try {
      await API.post("/auth/verify-otp", {
        email: signupEmail,
        otp: signupOtp,
      });

      setSignupStep(2);
      setSignupError("");
    } catch {
      setSignupError("Invalid OTP");
    }
  };

  // 🔥 REGISTER
  const handleSignup = async () => {
    if (!signupName || !signupPhone || !signupPassword) {
      setSignupError("Fill all fields");
      return;
    }

    try {
      await API.post("/auth/register", {
        fullName: signupName,
        email: signupEmail,
        password: signupPassword,
        phone: signupPhone,
        role: "CITIZEN",
      });

      alert("Registered successfully ✅");
      setIsFlipped(false);

    } catch {
      setSignupError("Signup failed");
    }
  };

  const goToSignup = () => {
    setIsFlipped(true);
    setSignupStep(1);
    setSignupOtpSent(false);
  };

  const goToSignin = () => {
    setIsFlipped(false);
    setLoginView('login');
    setLoginOtpSent(false);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md p-4 font-sans">
      <div className="flip-container w-full max-w-[400px] h-[600px] animate-slide-up">
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          {/* LOGIN */}
          <div className="flip-front bg-[#FDFAD8] border-4 border-[#47510B] rounded-[40px] p-8 flex flex-col justify-between">

            <button onClick={onClose}><X /></button>

            <div className="space-y-4">
              <input
                type="email"
                placeholder="EMAIL ADDRESS"
                value={loginEmail}
                onChange={(e) => setLoginEmail(e.target.value)}
                className="w-full p-4 border rounded-xl"
              />

              <input
                type="password"
                placeholder="••••••••"
                value={loginPassword}
                onChange={(e) => setLoginPassword(e.target.value)}
                className="w-full p-4 border rounded-xl"
              />

              {loginError && (
                <p className="text-[#AB1717] text-xs font-bold">
                  {loginError}
                </p>
              )}

              <button
                onClick={handleLogin}
                className="w-full bg-[#47510B] text-[#CAD23C] p-4 rounded-xl"
              >
                Access Dashboard
              </button>
            </div>

            <button onClick={goToSignup}>Join Tribe</button>
          </div>

          {/* SIGNUP */}
          <div className="flip-back bg-[#FFB6A9] border-4 border-[#AB1717] p-6 flex flex-col">

            <button onClick={goToSignin}>
              <ArrowLeft />
            </button>

            {signupStep === 1 ? (
              <>
                <input
                  type="email"
                  placeholder="EMAIL"
                  value={signupEmail}
                  onChange={(e) => setSignupEmail(e.target.value)}
                  className="p-3 border mb-3"
                />

                <button onClick={handleSendOtp}>Send OTP</button>

                {signupOtpSent && (
                  <>
                    <input
                      type="text"
                      placeholder="OTP"
                      value={signupOtp}
                      onChange={(e) => setSignupOtp(e.target.value)}
                      className="p-3 border mt-3"
                    />

                    <button onClick={handleVerifyOtp}>Verify OTP</button>
                  </>
                )}
              </>
            ) : (
              <>
                <input value={signupName} onChange={(e)=>setSignupName(e.target.value)} placeholder="Full Name" />
                <input value={signupPhone} onChange={(e)=>setSignupPhone(e.target.value)} placeholder="Phone" />
                <input type="password" value={signupPassword} onChange={(e)=>setSignupPassword(e.target.value)} placeholder="Password" />

                <button onClick={handleSignup}>Register</button>
              </>
            )}

            {signupError && <p className="text-red-500">{signupError}</p>}
          </div>

        </div>
      </div>
    </div>
  );
};

export default EntryCard;
